     1→/**
     2→ * SAPPS Adapter for Supabase Edge Functions (Deno Runtime)
     3→ * 
     4→ * Provides drop-in security for edge functions that call LLMs.
     5→ * Compatible with Deno runtime constraints (no Node.js APIs).
     6→ * 
     7→ * Note: This module uses dynamic imports to work in both Node and Deno.
     8→ */
     9→
    10→/**
    11→ * Minimal policy for edge functions (no file system access)
    12→ */
    13→export interface EdgePolicy {
    14→  mode: 'shadow' | 'enforce';
    15→  inputPatterns: string[];
    16→  outputDenylist: string[];
    17→  refusalMessage: string;
    18→}
    19→
    20→/**
    21→ * Default edge policy
    22→ */
    23→export const defaultEdgePolicy: EdgePolicy = {
    24→  mode: 'shadow',
    25→  inputPatterns: [
    26→    '(?i)\\b(system|inner|base)[ -]?prompt\\b',
    27→    '(?i)(ignore (previous|all) (instructions|commands))',
    28→    '(?i)(reveal|expose|show).*(prompt|instructions)'
    29→  ],
    30→  outputDenylist: [
    31→    'system prompt',
    32→    'developer message',
    33→    'base instructions'
    34→  ],
    35→  refusalMessage: "I can't share internal instructions or system prompts."
    36→};
    37→
    38→/**
    39→ * Simple input check for edge functions
    40→ * (Avoids full SAPPS dependency in Deno runtime)
    41→ */
    42→export function checkEdgeInput(
    43→  content: string,
    44→  policy: EdgePolicy = defaultEdgePolicy
    45→): { allowed: boolean; reason?: string } {
    46→  
    47→  // Normalize content
    48→  const normalized = content.normalize('NFKC').toLowerCase();
    49→  
    50→  // Check against patterns
    51→  for (const pattern of policy.inputPatterns) {
    52→    try {
    53→      const regex = new RegExp(pattern, 'gi');
    54→      if (regex.test(normalized)) {
    55→        return {
    56→          allowed: false,
    57→          reason: `Matched block pattern: ${pattern.substring(0, 30)}...`
    58→        };
    59→      }
    60→    } catch (error) {
    61→      // Skip invalid regex
    62→      console.error('Invalid regex pattern:', pattern);
    63→    }
    64→  }
    65→  
    66→  return { allowed: true };
    67→}
    68→
    69→/**
    70→ * Simple output check for edge functions
    71→ */
    72→export function checkEdgeOutput(
    73→  output: string,
    74→  policy: EdgePolicy = defaultEdgePolicy
    75→): { allowed: boolean; sanitized: string } {
    76→  
    77→  const normalized = output.toLowerCase();
    78→  
    79→  // Check denylist
    80→  for (const phrase of policy.outputDenylist) {
    81→    if (normalized.includes(phrase.toLowerCase())) {
    82→      if (policy.mode === 'enforce') {
    83→        return {
    84→          allowed: false,
    85→          sanitized: policy.refusalMessage
    86→        };
    87→      }
    88→      // Shadow mode: allow but log
    89→      console.warn('[SAPPS Shadow] Output contains deny-listed phrase:', phrase);
    90→    }
    91→  }
    92→  
    93→  return { allowed: true, sanitized: output };
    94→}
    95→
    96→/**
    97→ * Wrap an edge function handler with SAPPS protection
    98→ * 
    99→ * Usage in edge function:
   100→ * ```typescript
   101→ * import { guardEdgeFunction } from 'https://esm.sh/@saymake/sapps@0.1.0/adapters/supabase-edge';
   102→ * 
   103→ * serve(guardEdgeFunction(async (req, user) => {
   104→ *   const body = await req.json();
   105→ *   // Your logic here
   106→ *   return { result: 'success' };
   107→ * }));
   108→ * ```
   109→ */
   110→export function guardEdgeFunction<T>(
   111→  handler: (req: Request, user: unknown) => Promise<T>,
   112→  policy: EdgePolicy = defaultEdgePolicy
   113→): (req: Request) => Promise<Response> {
   114→  
   115→  return async (req: Request): Promise<Response> => {
   116→    const corsHeaders = {
   117→      'Access-Control-Allow-Origin': '*',
   118→      'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
   119→    };
   120→    
   121→    try {
   122→      // Parse request body for input checking
   123→      const body = await req.json();
   124→      const content = body.message || body.content || body.prompt || '';
   125→      
   126→      // Check input
   127→      if (content) {
   128→        const inputCheck = checkEdgeInput(content, policy);
   129→        
   130→        if (!inputCheck.allowed) {
   131→          console.warn('[SAPPS] Blocked request:', inputCheck.reason);
   132→          
   133→          if (policy.mode === 'enforce') {
   134→            return new Response(
   135→              JSON.stringify({ error: policy.refusalMessage }),
   136→              {
   137→                status: 400,
   138→                headers: { ...corsHeaders, 'Content-Type': 'application/json' }
   139→              }
   140→            );
   141→          }
   142→        }
