   400→  }
   401→  
   402→  /**
   403→   * Clear telemetry
   404→   */
   405→  clearTelemetry(): void {
   406→    this.telemetry = [];
   407→  }
   408→  
   409→  /**
   410→   * Get policy configuration
   411→   */
   412→  getPolicy(): Policy {
   413→    return this.policy;
   414→  }
   415→  
   416→  /**
   417→   * Update policy (creates new runtime instance internally)
   418→   */
   419→  updatePolicy(newPolicy: Policy): void {
   420→    this.policy = newPolicy;
   421→    this.mode = newPolicy.mode;
   422→
   423→    // Update provenance policy on all existing contexts
   424→    if (newPolicy.provenance) {
   425→      for (const [key, context] of this.toolContexts) {
   426→        this.toolContexts.set(key, setProvenancePolicy(context, newPolicy.provenance));
   427→      }
   428→    }
   429→  }
   430→
   431→  /**
   432→   * Check if provenance tracking is enabled
   433→   */
   434→  isProvenanceEnabled(): boolean {
   435→    return this.policy.provenance?.enabled ?? false;
   436→  }
   437→
   438→  /**
   439→   * Get provenance policy configuration
   440→   */
   441→  getProvenancePolicy(): ProvenancePolicy | undefined {
   442→    return this.policy.provenance;
   443→  }
   444→
   445→  /**
   446→   * Get all capability violations from recent telemetry
   447→   *
   448→   * Useful for monitoring and alerting on security issues in shadow mode.
   449→   */
   450→  getCapabilityViolations(): TelemetryEvent[] {
   451→    return this.telemetry.filter(
   452→      e => e.type === 'capability_violation' || (e.capabilityViolations && e.capabilityViolations.length > 0)
   453→    );
   454→  }
   455→
   456→  /**
   457→   * Get accumulated output provenance for a session
   458→   *
   459→   * Returns all provenance records from tool outputs in this session.
   460→   * Useful for understanding data flow and taint propagation.
   461→   */
   462→  getSessionOutputProvenance(sessionId?: string): Provenance[] {
   463→    const contextKey = sessionId || 'default';
   464→    const context = this.toolContexts.get(contextKey);
   465→    return context?.outputProvenance || [];
   466→  }
   467→}
