   470→ * Create a SAPPS runtime instance
   471→ * 
   472→ * @param options Runtime configuration
   473→ * @returns SAPPS runtime instance
   474→ * 
   475→ * @example
   476→ * ```typescript
   477→ * import { createRuntime, loadPolicy } from '@sunnypatneedi/spear';
   478→ * 
   479→ * const policy = loadPolicy('balanced.yaml');
   480→ * const runtime = createRuntime({ policy, mode: 'shadow' });
   481→ * 
   482→ * // Pre-process
   483→ * const preResult = await runtime.pre(messages, { sessionId: 'abc123' });
   484→ * 
   485→ * // Call LLM
   486→ * const llmOutput = await callLLM(preResult.messages);
   487→ * 
   488→ * // Post-process
   489→ * const postResult = await runtime.post({
   490→ *   output: llmOutput,
   491→ *   canary: preResult.canary
   492→ * });
   493→ * ```
   494→ */
   495→export function createRuntime(options: RuntimeOptions): SpearRuntime {
   496→  return new SpearRuntime(options);
   497→}
